from scipy.optimize import least_squares
tot=np.sum((dA_dt-dA_dt.mean())**2)
def run(f,p0,n=10):
    best=None
    for s in range(n):
        rng=np.random.default_rng(s)
        p=np.array(p0,float)+rng.normal(0,0.6,len(p0))
        try:
            r=least_squares(lambda p: f(p)-dA_dt, p, max_nfev=2000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return best, np.sum((f(best.x)-dA_dt)**2)/tot
